#include <stdio.h>
struct Record {int id;int score;};
int set_score(struct Record *record,int value){record->score=value;if(value<0||value>100)return 0;return 1;}

int main(void) {
int inputs[1]={80};int failures=0;
for(int i=0;i<1;i++) {struct Record record={7,80};int accepted=set_score(&record,inputs[i]);int expected=inputs[i]>=0&&inputs[i]<=100;int score=expected?inputs[i]:80;if(accepted!=expected||record.id!=7||record.score!=score) failures++;}
printf("cases=1 failures=%d\n",failures);
return 0;
}

